import{_ as t,c as a,o,ah as n,ao as s,ap as p}from"./chunks/framework.Dq2_gudl.js";const f=JSON.parse('{"title":"آن سوی پل رنگین‌کمان — پیمان خدا با همه موجودات زنده","description":"پل رنگین‌کمان تصویری زیباست، اما رنگین‌کمان کتاب مقدس بزرگ‌تر است: پیمانی جاودان که خدا با همه موجودات زنده بست.","frontmatter":{"title":"آن سوی پل رنگین‌کمان — پیمان خدا با همه موجودات زنده","description":"پل رنگین‌کمان تصویری زیباست، اما رنگین‌کمان کتاب مقدس بزرگ‌تر است: پیمانی جاودان که خدا با همه موجودات زنده بست."},"headers":[],"relativePath":"fa/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"fa/pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"fa/pets-in-heaven/rainbow-bridge-covenant.md"};function l(r,e,h,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>«می‌گویند او از پل رنگین‌کمان گذشته است. اما این فقط یک حرف قشنگ است — یا امیدی واقعی؟»</p><p class="pl-quote-soft">بخش شگفت‌انگیز این است: کتاب مقدس واقعاً رنگین‌کمان دارد و آن پیمان برای حیوانات بسته شد.</p></div><section class="pl-section"><h2>۱. آن رنگین‌کمان پیمانی با حیوانات بود</h2><p>پس از طوفان، خدا با نوح پیمان بست که دیگر زمین را با آب نابود نکند. اما طرف‌های آن پیمان تنها نوح و نسل او نبودند:</p><blockquote><p><strong>پیدایش ۹:۹-۱۳</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>به عبارت «<em>همه موجودات زنده</em>» توجه کنید — پرندگان، چهارپایان و همه جانوران زمین به‌عنوان طرف‌های پیمان نام برده شده‌اند. و خدا کمان خود را در ابر گذاشت تا نشانه‌ای باشد <strong>میان او و زمین، با همه موجودات زنده</strong>.</p><p>این یکی از نادیده‌گرفته‌شده‌ترین و مهربان‌ترین واقعیت‌های تمام کتاب مقدس است: <strong>خدا زمانی رسماً و جاودانه با حیوانات پیمان بست.</strong></p><p>پس نامی که انسان ساخته — «پل رنگین‌کمان» — چندان بی‌ربط نیست. کتاب مقدس می‌گوید آن نور نشانه است و نشانه هرگز به معنای «پایان» نیست. به معنای «ادامه دارد» است.</p></section><section class="pl-section"><h2>۲. در جهان آینده، آن‌ها در آرامش می‌خوابند</h2><p>وقتی اشعیا جهانی را که خدا خواهد ساخت توصیف می‌کند، حیوانات در مرکز صحنه‌اند:</p><blockquote><p><strong>اشعیا ۶۵:۲۵</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>و مکاشفه اجازه می‌دهد بشنویم چه کسی در پرستش نهایی می‌خواند:</p><blockquote><p><strong>مکاشفه ۵:۱۳</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>«هر آفریده‌ای» پرستش می‌کند. نه فقط انسان‌ها.</p><p>و مزامیر همه را در یک خط کوتاه خلاصه می‌کند:</p><blockquote><p><strong>مزامیر ۱۵۰:۶</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>هر چه نفس دارد — از جمله او — درون آن سرود است.</p></section><section class="pl-section"><h2>۳. پس آن سوی پل، وعده‌ای است</h2><p>ما نمی‌توانیم از جانب خدا وعده‌ای بیفزاییم. اما می‌توانیم درون آنچه او گفته است بمانیم: با همه موجودات زنده پیمان بست؛ جهانی که خواهد ساخت حیواناتی در صلح دارد؛ پرستش نهایی او «هر آفریده» را در بر می‌گیرد؛ هر چه نفس دارد او را خواهد ستود.</p><p>این آیات نمی‌گویند «حیوان شما قطعاً آنجاست». اما این دعا را کاملاً مشروع می‌کنند: «خداوندا، باشد که او درون وعده تو باشد.» و این همان خدایی است که برای حیوانات رنگین‌کمانی گذاشت.</p><p class="pl-quote-soft">بیندیشید: اگر خدا برای حیوانات رنگین‌کمانی گذاشت، آیا او را به یاد نخواهد آورد؟</p></section><div class="pl-quote"><p>«تو کمان خود را در ابر گذاشتی، نشانه‌ای با همه موجودات زنده.<br>وقتی آن نور را ببینم، او را به یاد خواهم آورد.<br>باشد که او درون وعده تو در آرامش باشد، همان‌گونه که وعده دادی.<br>و باشد که پیمان تو مرا در روزهای دلتنگیم نگه دارد. آمین.»</p></div><section class="pl-section"><h2>یک آیین کوچک برای شما</h2><p>اگر پس از باران رنگین‌کمانی پدیدار شد، بگذارید نشانه شما باشد. چند لحظه آنجا بایستید و با او حرف بزنید — نه نتیجه‌گیری لازم است، نه کامل کردن جمله. در کتاب مقدس آن نور همیشه «نشانه پیمان» بود و نشانه یعنی خدا فراموش نکرده است.</p><p><a href="/fa/pets-in-heaven/">← بازگشت به Pets in Heaven</a> ｜ بعدی: <a href="/fa/pets-in-heaven/permission-to-grieve">اجازه داشتن برای اندوه</a></p></section><div class="pl-cta"><h2>جاهایی که با هم دیدید را نگه دارید.</h2><p>عکس‌های او را به کارت یادبود، پوستر یا فیلمی کوتاه تبدیل کنید تا روزهایی که با هم قدم زدید شکلی ماندگار بگیرند.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">دانلود از App Store</a></div><div class="pl-bible"><h3>بگذارید کلام خدا همراهتان بماند</h3><p>همهٔ آیات این نوشته از کتاب مقدس است. با اپلیکیشن Rainbow Bible می‌توانید هر زمان کتاب مقدس را بخوانید و ویجت «آیهٔ روز» را تنظیم کنید — نوری کوچک برای روزهایی که دلتان تنگ است.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="ابزارک Rainbow Bible، آیهٔ ۲ تیموتائوس ۲:۱۳" loading="lazy"><figcaption>آیهٔ روز روی صفحهٔ اصلی</figcaption></figure><figure><img src="'+p+'" alt="اپ Rainbow Bible — موضوع حیوانات خانگی در بهشت، متی ۱۰:۲۹-۳۱" loading="lazy"><figcaption>در موضوع «حیوانات خانگی در بهشت» بخوانید</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">دریافت Rainbow Bible از App Store</a></div>',8)])])}const g=t(i,[["render",l]]);export{f as __pageData,g as default};
